from unittest.mock import Mock

class ProgressSaveError(Exception):
    pass

def save_progress(text, writer):
    try:
        writer(text)
    except OSError as error:
        raise ProgressSaveError('progress was not saved') from error
    return 'saved'

failure = Mock(side_effect=OSError('disk full'))
try:
    save_progress('lesson-12', failure)
except ProgressSaveError as error:
    assert isinstance(error.__cause__, OSError)
else:
    raise AssertionError('failure was hidden')
failure.assert_called_once_with('lesson-12')
success = Mock()
assert save_progress('lesson-12', success) == 'saved'
success.assert_called_once_with('lesson-12')
print('save failure tests passed')

